    const float B = 0.30 * 2.0;
    const float C = 0.10;
    const float D = 0.20;
    const float E = 0.01;
    const float F = 0.30;
    float3 mapped =
        ((color * (A * color + C * B) + D * E) / (color * (A * color + B) + D * F)) - E / F;
    return mapped / tonemapper.x;
